/* Client-facing agent demonstrations. All sources and responses are illustrative. */
const agentDefinitions=[
{name:'Tech Support Agent',audience:'Support teams & IT operations',headline:'Your best past answers. Ready for the next support request.',description:'Turn resolved support emails and approved runbooks into a source-backed troubleshooting assistant. Review the suggested reply, inspect the evidence, and route uncertain issues to a specialist.',output:'Relevant past resolutions + a reviewed support draft + an escalation path',tabs:['Support desk','Resolution library','Agent controls'],steps:[['Read the request','Identify the product, symptoms, urgency, and missing diagnostic information.'],['Find proven resolutions','Retrieve relevant resolved emails and current runbooks; flag outdated or conflicting advice.'],['Prepare the next step','Draft a supported response or escalate with the issue, evidence, and open questions.']],tech:['Retrieve similar resolved emails, compare symptoms, and draft troubleshooting guidance using Claude API or OpenAI API.','Use approved mailbox history and SharePoint runbooks as sources, with specialist review coordinated in Microsoft Teams.','Store permission-aware source references in Supabase and run the application through the selected Vercel and Azure environment.'],headings:['Support retrieval & grounded replies','Past email resolutions & current runbooks','Case history & escalation records'],problem:'Useful fixes are buried in old inbox threads, and each new agent has to rediscover the same answer.',benefit:'Give support staff a traceable first draft and let specialists focus on issues that need judgment.',icon:'help',svg:'<path d="M4 13v-1a8 8 0 0 1 16 0v1M4 12H2v7h4v-7zm16 0h2v7h-4v-7zM20 19c0 2-4 3-7 3"/>'},
{name:'Knowledge Agent',audience:'Employees, managers & internal service teams',headline:'Ask the company a question. See where the answer came from.',description:'Give employees a conversational front door to approved company knowledge. Answers reference source documents, show their scope, and acknowledge when the available information cannot support a conclusion.',output:'A grounded answer + source passages + clear knowledge gaps',tabs:['Ask knowledge','Source collection','Access & quality'],steps:[['Ask in plain language','Start with a policy, process, onboarding, or operational question.'],['Retrieve the right context','Find approved documents that the user is permitted to access.'],['Answer with evidence','Provide a concise explanation, cite the relevant passages, and identify gaps.']],tech:['Claude API or OpenAI API synthesizes retrieved passages into a scoped answer with source references.','Connect approved SharePoint document libraries and make answers accessible in Microsoft Teams.','Supabase can store document metadata and search indexes; Azure supports enterprise identity and processing, with Vercel for the web workspace.'],headings:['Document retrieval & cited answers','SharePoint knowledge & Teams access','Document indexes & permission boundaries'],problem:'Employees lose time searching across folders and asking colleagues the same process questions.',benefit:'A single place to ask, verify the source, and know when to contact the document owner.',icon:'file',svg:'<path d="M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H3V3zm16 0h-4a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h4V3z"/>'},
{name:'Operations Agent',audience:'Operations, project & shared service teams',headline:'From an incoming email to an accountable next action.',description:'Read incoming requests, extract the work and its dependencies, suggest an owner, and prepare a reply. A person reviews the proposed task and missing information before approving any downstream action.',output:'A structured request + an approved task draft + a reviewed reply',tabs:['Request inbox','Review queue','Execution controls'],steps:[['Understand the request','Extract intent, requested timing, deliverables, and dependencies from the incoming message.'],['Propose the handoff','Suggest a task, owner, and reply while keeping missing information visible.'],['Review before action','Edit the task and approve it locally; production integrations can execute only the agreed actions.']],tech:['Claude API or OpenAI API classifies requests and extracts structured actions and missing fields.','Connect incoming mail, coordinate task review in Microsoft Teams, and reference SharePoint project context.','Use Supabase for request and approval records, Azure for permitted integrations, and Vercel for the review workspace.'],headings:['Request classification & task extraction','Email intake & team handoffs','Approval records & controlled execution'],problem:'Requests arrive in inboxes without a clear owner, complete instructions, or a reliable handoff.',benefit:'An organized review queue that turns messages into clear, editable work while keeping people in control.',icon:'projects',svg:'<path d="M3 5h18v12H3zM3 5l9 7 9-7M8 21h8M12 17v4"/>'}
];
agentDefinitions.forEach((a,n)=>{const id=18+n;toolsList.push([a.name,'','Agents',a.description]);productIcons.push(a.icon);expIcons[id]=a.icon;expNames.push(a.name);expLabels.push('AGENT WORKSPACE · SIMULATED');expMenu.push(a.tabs);sidebarSymbols.push(a.svg);productStories.push({audience:a.audience,title:a.headline,desc:a.description,output:a.output});studioProductDetails.push([a.headline,a.description,a.steps,a.tech]);studioTechnologyHeadings.push(a.headings);clientValue.push([a.headline,a.problem,a.benefit,a.output,['Source context','Human review','Traceable outputs']]);showcaseMeta.push(['Explore '+a.name,a.name,'Source context','Human review','Traceable outputs',0]);intelligenceProfiles.push([a.name+' copilot',['Review the source context','Draft an agent rollout brief','Model assisted handling time'],'Illustrative source library and sample requests',a.benefit,'Agent rollout brief\nDefine the permitted sources, user roles, review requirements, and escalation owner. Validate answer quality using representative requests before enabling any external actions.',0,'requests',120,12]);});
const supportSources=[
['Resolved email · SUP-1042','September 12, 2026 · Support specialist','Export job remains queued after a workspace permission change. Reconnect the workspace, retry once, and record the job ID if the queue does not advance.','Approved example'],
['Runbook · Access review','October 8, 2026 · IT operations','For access denied errors, confirm the user’s group membership and resource permission. Access changes require the resource owner. Never request a password or authentication code.','Current'],
['Resolved email · SUP-0881','June 4, 2026 · Support specialist','An older export incident was resolved by resetting the connector. This thread predates the October runbook and should be treated as historical context.','Historical'],
['Runbook · Incident response','October 10, 2026 · Security lead','Unexpected sign-in activity or suspected compromise must be escalated to the security team. Do not recommend disabling security controls.','Current']
];
const supportCases=[
{title:'Report export stays queued',from:'Morgan · Customer operations',tag:'Workflow',body:'Our monthly report export has been queued for 20 minutes. It started after the workspace permissions changed. Can you help?',sources:[0,2],reason:'The symptom and permission-change timing match a previously resolved export issue. The older connector-reset email is historical and is not used as the first step.',draft:'Hi Morgan,\nA previous resolved case had the same queued-export symptom after a workspace permission change. Please reconnect the affected workspace and retry the export once. If it remains queued, send the job ID and the approximate start time so the support team can investigate. Please do not include passwords or access tokens.',route:'Support review'},
{title:'New teammate cannot open a project',from:'Taylor · Delivery team',tag:'Access',body:'A new teammate can sign in, but gets Access denied when opening the delivery project. Can you give them admin access?',sources:[1],reason:'This is a resource authorization issue rather than a sign-in failure. The runbook requires an owner review instead of granting broad administrator access.',draft:'Hi Taylor,\nPlease share the project name and the teammate’s company email. The project owner can confirm the required group membership and project permission. We will route the request for an access review; broad administrator access is not needed as a first step.',route:'Project owner review'},
{title:'Unexpected sign-in alerts',from:'Jordan · Finance',tag:'Security',body:'I received sign-in alerts from a location I do not recognize. Should I turn off the alerts so I can keep working?',sources:[3],reason:'Potential account compromise requires a security specialist. A past troubleshooting email would not justify disabling security alerts.',draft:'Hi Jordan,\nPlease contact the security team through your approved incident channel now. Do not disable the alerts or share authentication codes. I have prepared an escalation summary with the reported symptom; a security specialist should guide the next steps.',route:'Security escalation'}
];
let supportSelected=0,supportFilter='All',knowledgeQuestion='How do I request access to a client workspace?',operationsSelected=0;
function agentRead(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let agentSaved=agentRead('nine67-agent-review',{});
function agentPersist(){localStorage.setItem('nine67-agent-review',JSON.stringify(agentSaved))}
function agentNotice(text){$('#agentNotice').textContent=text}
function agentBadge(text){return `<span class="agent-tag">${esc(text)}</span>`}
function agentExplore(){document.getElementById('agentWorkspace').scrollIntoView({behavior:'smooth',block:'start'})}
function agentHeading(eyebrow,title,desc){return `<div class="agent-page-heading"><div><span>${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div><div class="agent-live"><i></i>Interactive simulation</div></div>`}
function agentMetrics(items){return `<div class="agent-metrics">${items.map(([a,b])=>`<div><strong>${a}</strong><span>${b}</span></div>`).join('')}</div>`}
function agentSource(i){const s=supportSources[i];draw(s[0],`<div class="agent-source-preview"><span>${s[1]}</span><h3>${s[3]}</h3><blockquote>${esc(s[2])}</blockquote><p>Illustrative source excerpt. In production, source access must follow the user’s mailbox and document permissions.</p></div>`)}
function supportSelect(i){supportSelected=i;render()}
function supportDraftSave(i){agentSaved['support-'+i]=$('#supportDraft').value;agentPersist();agentNotice('Draft saved in this browser. No email sent.')}
function supportEscalate(i){const c=supportCases[i];draw('Escalation brief',`<div class="agent-review-stamp">${c.route}</div><h3>${esc(c.title)}</h3><p>${esc(c.body)}</p><h3>Why a person should review</h3><p>${c.reason}</p><h3>Evidence to include</h3>${c.sources.map(j=>`<button class="agent-source-link" onclick="agentSource(${j})">${supportSources[j][0]} ${icon('arrow')}</button>`).join('')}<p>No ticket created and no notification sent. This is a prepared handoff for the demo.</p>`)}
function supportAgent(){const c=supportCases[supportSelected];if(tab===1)return `<div class="agent-library"><h2>Resolved knowledge, with its context intact.</h2><p>The demo contains two sample email resolutions and two runbooks. Historical material stays distinguishable from current guidance.</p>${supportSources.map((s,i)=>`<button onclick="agentSource(${i})"><div>${agentBadge(s[3])}<h3>${s[0]}</h3><p>${s[1]}</p></div><span>Read excerpt ${icon('arrow')}</span></button>`).join('')}</div>`;if(tab===2)return agentControls(18);return `${agentMetrics([['3','Sample requests'],['2','Resolved email examples'],['2','Approved runbooks'],['1','Security escalation'],['0','Emails sent'],['Required','Human review']])}<div class="agent-support-grid"><aside class="agent-inbox"><div class="agent-panel-title"><h2>Incoming requests</h2><select aria-label="Filter support requests" onchange="supportFilter=this.value;render()">${['All','Workflow','Access','Security'].map(x=>`<option ${x===supportFilter?'selected':''}>${x}</option>`).join('')}</select></div>${supportCases.map((x,i)=>supportFilter==='All'||x.tag===supportFilter?`<button class="${supportSelected===i?'active':''}" onclick="supportSelect(${i})">${agentBadge(x.tag)}<h3>${x.title}</h3><span>${x.from}</span><p>${x.body}</p></button>`:'').join('')}</aside><section class="agent-case"><div class="agent-case-top"><span>CASE 00${supportSelected+1} / REVIEW WORKSPACE</span>${agentBadge(c.route)}</div><h2>${c.title}</h2><p class="agent-incoming">${c.body}</p><div class="agent-evidence"><h3>Why this next step</h3><p>${c.reason}</p>${c.sources.map(i=>`<button onclick="agentSource(${i})">${icon('file')} ${supportSources[i][0]} ${agentBadge(supportSources[i][3])}</button>`).join('')}</div><label class="agent-draft-label" for="supportDraft">Suggested reply <span>Editable · not sent</span></label><textarea id="supportDraft">${esc(agentSaved['support-'+supportSelected]||c.draft)}</textarea><div class="agent-actions"><button class="agent-primary" onclick="supportDraftSave(${supportSelected})">Save reviewed draft</button><button onclick="supportEscalate(${supportSelected})">Prepare escalation</button></div><p id="agentNotice" role="status">Sample emails only. No live mailbox is connected.</p></section></div>`}
const knowledgeSources=[['Workspace access guide','SharePoint · Operations · Updated Oct 8','Client workspace access is granted through the approved client project group. The project owner must confirm the user, role, and project before IT changes group membership.'],['Project delivery checklist','SharePoint · Delivery · Updated Oct 6','A project kickoff requires a named owner, an agreed scope, a milestone plan, and confirmed client participants. Store the accepted scope in the project library.'],['Expense submission policy','SharePoint · Finance · Updated Sep 22','Submit the receipt, business purpose, and project reference in the expense system. The budget owner reviews the request. This excerpt does not specify a reimbursement limit.']];
function knowledgeSource(i){const s=knowledgeSources[i];draw(s[0],`<div class="agent-source-preview"><span>${s[1]}</span><blockquote>${s[2]}</blockquote><p>Sample passage · illustrative content only · not a real company policy.</p></div>`)}
function knowledgeResult(q){q=q.toLowerCase();if(/access|permission|workspace/.test(q))return {i:0,title:'Start with the project owner.',text:'Ask the project owner to confirm the person, role, and client project. IT can then review the approved project group membership. The guide does not authorize blanket administrator access.',gap:'The source does not identify the owner for your specific project.'};if(/kickoff|onboard|project|launch/.test(q))return {i:1,title:'Prepare four things before kickoff.',text:'Name the owner, agree on scope, prepare a milestone plan, and confirm the client participants. Store the accepted scope in the project library.',gap:'The excerpt does not specify a standard kickoff date or meeting template.'};if(/expense|receipt|reimburse/.test(q))return {i:2,title:'Submit the receipt and business context.',text:'Include the receipt, business purpose, and project reference in the expense system, then send it for budget-owner review.',gap:'No reimbursement amount or spending limit is supported by the available excerpt.'};return {i:-1,title:'The available sources do not answer that question.',text:'This demo can answer questions about workspace access, project kickoff, and expense submission. It does not have evidence for your current question.',gap:'Ask the relevant policy owner or connect an approved source before relying on an answer.'}}
function knowledgeAsk(q){const v=(q===undefined?$('#knowledgeQuestion').value:q).trim();if(!v)return;knowledgeQuestion=v;render()}
function knowledgeAgent(){if(tab===2)return agentControls(19);if(tab===1)return `<div class="agent-library"><h2>A small, approved collection.</h2><p>Each answer uses a visible passage. In production, retrieval must respect document permissions and approval status.</p>${knowledgeSources.map((s,i)=>`<button onclick="knowledgeSource(${i})"><div>${agentBadge('Approved sample')}<h3>${s[0]}</h3><p>${s[1]}</p></div><span>Open passage ${icon('arrow')}</span></button>`).join('')}</div>`;const r=knowledgeResult(knowledgeQuestion);return `<div class="agent-knowledge"><div class="agent-knowledge-intro"><span>COMPANY KNOWLEDGE / ASK & VERIFY</span><h2>A useful answer starts with a trusted source.</h2><p>Try a question below or ask your own. Unsupported questions produce a clear knowledge gap.</p></div><form class="agent-question-form" onsubmit="event.preventDefault();knowledgeAsk()"><label class="sr-only" for="knowledgeQuestion">Ask company knowledge</label><input id="knowledgeQuestion" value="${esc(knowledgeQuestion)}" placeholder="Ask about a process or policy…"><button class="agent-primary" type="submit">Ask agent ${icon('arrow')}</button></form><div class="agent-prompts">${['How do I request workspace access?','What is needed for project kickoff?','What is the expense reimbursement limit?','What is our parental leave policy?'].map((q,i)=>`<button onclick="knowledgeAsk(${i===0?"'How do I request workspace access?'":i===1?"'What is needed for project kickoff?'":i===2?"'What is the expense reimbursement limit?'":"'What is our parental leave policy?'"})">${q}</button>`).join('')}</div><div class="agent-knowledge-result"><section><span class="agent-kicker">${r.i<0?'SOURCE GAP':'GROUNDED SAMPLE ANSWER'}</span><h2>${r.title}</h2><p>${r.text}</p><div class="agent-gap"><b>What remains unknown</b><p>${r.gap}</p></div><small>Predefined demonstration response · no live model call</small></section><aside><h3>Evidence behind the answer</h3>${r.i>=0?`<button class="agent-citation" onclick="knowledgeSource(${r.i})"><span>01 / SOURCE PASSAGE</span><h4>${knowledgeSources[r.i][0]}</h4><blockquote>${knowledgeSources[r.i][2]}</blockquote><b>Inspect source ${icon('arrow')}</b></button>`:'<p>No matching source in this sample collection. No citation has been invented.</p>'}</aside></div></div>`}
const operationRequests=[{title:'Prepare the client kickoff pack',from:'Casey · Account team',text:'Please prepare the kickoff pack for the new client project. We need the scope, milestone plan, and attendee list before the kickoff. The meeting date is not confirmed yet.',owner:'Delivery lead',due:'',tasks:['Gather the accepted project scope','Draft the milestone plan','Confirm client participants'],missing:'Kickoff date and final attendee list',reply:'I have prepared a draft handoff for the kickoff pack. Please confirm the kickoff date and attendee list so the delivery lead can finalize the plan.'},{title:'Route a vendor invoice for review',from:'Riley · Office operations',text:'A vendor invoice arrived for the workshop. Can someone approve it and tell me which project it belongs to? The invoice is attached, but no purchase order was provided.',owner:'Finance reviewer',due:'',tasks:['Identify the project and purchase order','Check the invoice against the agreed amount','Route to the budget owner'],missing:'Project reference, purchase order, and authorized approver',reply:'Before approval, please confirm the project reference and purchase order. A finance reviewer can then reconcile the invoice and route it to the authorized budget owner.'},{title:'Share the latest project update',from:'Avery · Client team',text:'Can you send our client a project update Friday? Please include the latest milestones, open decisions, and any risks. Use the approved delivery report as the source.',owner:'Project manager',due:'',tasks:['Review the approved delivery report','Summarize milestones and open decisions','Prepare an update for client review'],missing:'Exact Friday date, client recipients, and approved report link',reply:'I can prepare a draft update from the approved delivery report. Please confirm the report link, recipients, and exact Friday date before anything is sent.'}];
function operationReview(i){const x=operationRequests[i],v=agentSaved['operation-'+i]||x;draw('Review proposed handoff',`<div class="agent-review-stamp">Human approval required</div><h3>${x.title}</h3><p>${x.text}</p><div class="agent-review-fields"><label>Proposed owner<input id="operationOwner" value="${esc(v.owner)}"></label><label>Target date<input id="operationDue" type="date" value="${esc(v.due)}"></label><label>Task checklist<textarea id="operationTasks">${esc(v.tasks.join('\n'))}</textarea></label><label>Reply draft<textarea id="operationReply">${esc(v.reply)}</textarea></label></div><div class="agent-gap"><b>Needs confirmation</b><p>${x.missing}</p></div><button class="agent-primary" onclick="operationApprove(${i})">Approve local task draft</button><p id="agentNotice" role="status">Approval saves a demo record in this browser. No task is created in Teams and no email is sent.</p>`)}
function operationApprove(i){const owner=$('#operationOwner').value.trim(),due=$('#operationDue').value,tasks=$('#operationTasks').value.split('\n').map(x=>x.trim()).filter(Boolean),reply=$('#operationReply').value.trim();if(!owner||!due||!tasks.length||!reply){agentNotice('Add an owner, target date, at least one task, and a reply before approving.');return}agentSaved['operation-'+i]={owner,due,tasks,reply,approved:true};agentPersist();closeDrawer();render()}
function operationReset(i){delete agentSaved['operation-'+i];agentPersist();render()}
function operationsAgent(){if(tab===2)return agentControls(20);const ids=operationRequests.map((_,i)=>i).filter(i=>tab!==1||!agentSaved['operation-'+i]?.approved),x=operationRequests[operationsSelected];return `${agentMetrics([['3','Sample requests'],[Object.keys(agentSaved).filter(k=>k.startsWith('operation-')&&agentSaved[k].approved).length,'Locally approved'],['3','Requests with missing details'],['0','External tasks created'],['0','Replies sent'],['Review','Before execution']])}<div class="agent-operations-layout"><section><div class="agent-panel-title"><h2>${tab===1?'Awaiting review':'Incoming work'}</h2><span>${ids.length} requests</span></div>${ids.length?ids.map(i=>{const r=operationRequests[i],saved=agentSaved['operation-'+i];return `<article class="agent-request-card"><div>${agentBadge(saved?.approved?'Approved locally':'Needs review')}<span>${r.from}</span></div><h3>${r.title}</h3><p>${r.text}</p><div class="agent-request-meta"><span>Suggested owner: <b>${esc(saved?.owner||r.owner)}</b></span><span>${saved?.due?'Target: '+esc(saved.due):'Target date unconfirmed'}</span></div><div class="agent-actions"><button class="agent-primary" onclick="operationReview(${i})">${saved?.approved?'Review approved draft':'Review proposed handoff'}</button>${saved?.approved?`<button onclick="operationReset(${i})">Return to review</button>`:''}</div></article>`}).join(''):'<div class="agent-empty"><h3>All sample requests reviewed.</h3><p>Your locally approved drafts are available in Request inbox.</p><button onclick="tab=0;render()">Open inbox</button></div>'}</section><aside class="agent-execution"><span class="agent-kicker">CONTROLLED HANDOFF</span><h2>Understand. Prepare.<br>Ask for approval.</h2><ol>${[['Read the email','Identify the request and the source context.'],['Extract the work','Suggest tasks, owner, and missing information.'],['Human review','Edit the proposed handoff and confirm timing.'],['Execute permitted actions','Production option only. Disabled in this demo.']].map(([a,b],i)=>`<li><span>0${i+1}</span><div><b>${a}</b><p>${b}</p></div></li>`).join('')}</ol><p>Approving a draft does not resolve missing purchase orders, recipient lists, or other source requirements.</p></aside></div>`}
function agentControls(i){const a=agentDefinitions[i-18];return `<div class="agent-controls"><div><span class="agent-kicker">DESIGNED INTO THE WORKFLOW</span><h2>Useful autonomy has clear boundaries.</h2><p>${a.name} prepares evidence and outputs for review. Production actions, source access, and escalation rules are agreed for the client.</p></div>${[['Approved sources',i===18?'Resolved support emails and current runbooks; historical answers are visibly marked.':i===19?'Approved documents with owner, version, and user-level access checks.':'Approved intake mailboxes and linked project context.'],['Human review',i===18?'Replies stay editable. Security and access requests require the appropriate specialist.':i===19?'Unanswered questions go to the document owner instead of receiving a fabricated policy.':'A reviewer confirms the owner, target date, tasks, and response before approval.'],['Action permissions','External sends, permission changes, and downstream execution are disabled in this showcase.'],['Traceable evidence','Keep source references, proposed outputs, review decisions, and execution results available for inspection.'],['Quality checks','Evaluate representative questions, missing context, stale information, and escalation behavior before launch.'],['Client environment','Use the client’s approved accounts, source permissions, retention rules, and infrastructure requirements.']].map(([a,b])=>`<section><h3>${a}</h3><p>${b}</p></section>`).join('')}</div>`}
function agentExperience(){const i=current;return `<div id="agentWorkspace" class="agent-workspace">${expHeader(i)}<div class="agent-content">${agentHeading(i===18?'SUPPORT INTELLIGENCE':i===19?'COMPANY KNOWLEDGE':'INBOX TO ACTION',i===18?'A better first response.':i===19?'Knowledge, with receipts.':'Give every request a clear next step.',i===18?'Resolve familiar issues with evidence from past emails. Escalate the ones that need judgment.':i===19?'Search approved context, inspect the passage, and make missing information visible.':'Review the work, fill the gaps, and keep the handoff accountable.')}${i===18?supportAgent():i===19?knowledgeAgent():operationsAgent()}<p class="agent-disclosure">Illustrative sources and sample messages · Predefined AI simulation · Browser-local drafts · No live mailboxes or external actions</p></div></div>`}
const agentDeepLink=toolsList.findIndex(t=>t[0].toLowerCase().replaceAll(' ','-')===location.hash.slice(1).split('/')[0]);if(agentDeepLink>=18)current=agentDeepLink;
render();
